WITH flagged AS (SELECT *, CASE WHEN started_at - LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) > INTERVAL '90' DAY THEN 1 ELSE 0 END AS is_new_burst FROM sessions), sessions_sessions AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, browser, started_at, country, is_new_burst, CASE WHEN browser RLIKE '^(Edge|Safari)$' THEN 'CORE' WHEN browser RLIKE '^(Chrome|Firefox)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS browser_zone FROM sessions_sessions ORDER BY browser_zone DESC;
